CREATE TABLE IF NOT EXISTS warehouse_transfer (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '调拨业务ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',document_sn VARCHAR(64) NOT NULL COMMENT '调拨单号DB前缀',request_key VARCHAR(64) NOT NULL COMMENT '创建幂等请求',request_hash CHAR(64) NOT NULL COMMENT '不可变创建摘要',
 source_store VARCHAR(64) NOT NULL COMMENT '原虚仓',target_store VARCHAR(64) NOT NULL COMMENT '目的虚仓',owner_code VARCHAR(64) NOT NULL COMMENT '双方同一货主',source_real VARCHAR(64) NOT NULL COMMENT '出库实仓',target_real VARCHAR(64) NOT NULL COMMENT '目的实仓',
 state VARCHAR(24) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT待审核、ACTIVE执行中、STOPPING停止剩余、STOPPED未出库余额已释放、COMPLETED已全部入库',stock_state VARCHAR(24) NOT NULL DEFAULT 'UNHELD' COMMENT 'UNHELD未占用、HELD原批次已占用、RELEASED未出库剩余已释放',
 reason VARCHAR(1000) NOT NULL COMMENT '调拨业务原因',created_by VARCHAR(64) NOT NULL COMMENT '创建人',approved_by VARCHAR(64) NOT NULL DEFAULT '' COMMENT '审核人',control_version BIGINT NOT NULL DEFAULT 1 COMMENT '审核及操作版本',
 lease_token VARCHAR(64) NULL COMMENT '后台执行租约令牌',lease_until DATETIME NULL COMMENT '租约到期时间',attempts INT NOT NULL DEFAULT 0 COMMENT '失败退避次数',next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下次可执行时间',last_error VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '最近执行错误',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近处理时间',
 UNIQUE KEY company_sn(company_code,document_sn) COMMENT '单号唯一',UNIQUE KEY company_request(company_code,request_key) COMMENT '创建幂等',KEY company_page(company_code,create_time,id) COMMENT '默认日期分页',KEY due_work(company_code,state,next_attempt_at,id) COMMENT '只扫描到期未完成任务'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='同公司同货主跨实仓调拨，一张业务单关联两侧仓库执行';
CREATE TABLE IF NOT EXISTS warehouse_transfer_line (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '调拨原行ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',transfer_id BIGINT NOT NULL COMMENT '调拨业务ID',sku_sn VARCHAR(128) NOT NULL COMMENT '库存SKU',goods_name VARCHAR(200) NOT NULL COMMENT '创建时商品名称',
 source_batch_id BIGINT NOT NULL COMMENT '原库存批次ID',batch_code VARCHAR(128) NOT NULL COMMENT '原批次',inventory_type VARCHAR(2) NOT NULL COMMENT '原正次品ZP或CP',unit_cost DECIMAL(18,2) NOT NULL COMMENT '原批次单位成本',stock_unit VARCHAR(16) NOT NULL COMMENT '原库存单位',
 quantity BIGINT NOT NULL COMMENT '计划调拨数量',out_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '原仓实际出库已入账',in_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '目的仓实际入库已入账',recovered_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '原仓收回已入账',released_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '未出库剩余已释放',
 KEY company_document(company_code,transfer_id,id) COMMENT '业务单明细及批量列表汇总'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='调拨数量投影；实物变化以库存事务流水为准';
CREATE TABLE IF NOT EXISTS warehouse_transfer_execution (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '仓库执行ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',transfer_id BIGINT NOT NULL COMMENT '原调拨业务ID',document_sn VARCHAR(64) NOT NULL COMMENT '独立仓库单号DBO出库、DBI入库、DBH收回',side VARCHAR(8) NOT NULL COMMENT 'OUT原仓出库、IN目的收货、RECOVER原仓收回',
 store_code VARCHAR(64) NOT NULL COMMENT '本执行虚仓',connection_id BIGINT NOT NULL COMMENT '原仓库连接ID，用于连接引用索引',route_json MEDIUMTEXT NOT NULL COMMENT '审核时仓库连接货主映射快照，不含密钥',plan_json MEDIUMTEXT NOT NULL COMMENT '原行计划数量快照',dispatch_state VARCHAR(24) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待下发、SENDING发送中、ACCEPTED仓库受理、FAILED明确失败、UNKNOWN结果不明、CANCELED仓库停止',
 external_order VARCHAR(128) NOT NULL DEFAULT '' COMMENT '仓库原单号',receipt_final TINYINT NOT NULL DEFAULT 0 COMMENT '仓库最终确认，不代表全量实收',review_pending TINYINT NOT NULL DEFAULT 0 COMMENT '回传冲突待仓库更正，禁止释放',carrier_code VARCHAR(64) NOT NULL DEFAULT '' COMMENT '仓库实际物流公司编码',waybill VARCHAR(200) NOT NULL DEFAULT '' COMMENT '仓库实际运单号',last_error VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '该侧最近交互错误',
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '执行单创建时间',UNIQUE KEY company_sn(company_code,document_sn) COMMENT '仓库执行单号唯一',KEY company_connection(company_code,connection_id,id) COMMENT '配置被业务执行使用后不可变更',KEY document_side(company_code,transfer_id,side,id) COMMENT '同单两侧及独立收回追溯'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='调拨两侧独立奇门DBCK和DBRK执行；收回独立DBRK';
CREATE TABLE IF NOT EXISTS warehouse_control_event (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '回传持久化事件ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',transfer_id BIGINT NOT NULL COMMENT '原调拨ID',execution_id BIGINT NOT NULL COMMENT '原仓库执行ID',message_id VARCHAR(128) NOT NULL COMMENT '仓库原增量消息ID',payload_hash CHAR(64) NOT NULL COMMENT '相同消息内容不可改变',payload_json MEDIUMTEXT NOT NULL COMMENT '验签及原行校验后的实物事件',source_log_id BIGINT NOT NULL DEFAULT 0 COMMENT '原始仓库交互证据',state VARCHAR(16) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING待入账、POSTED已入账、FAILED待补偿',last_error VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '入账错误',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收到事件时间',
 UNIQUE KEY original_message(company_code,execution_id,message_id) COMMENT '原执行及消息去重',KEY pending_post(company_code,transfer_id,state,id) COMMENT '按单扫描待补偿事件'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='调拨回传先落库后入账；库存成功投影失败按同一事件补偿';
CREATE TABLE IF NOT EXISTS warehouse_reconciliation (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '库存对账任务ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',document_sn VARCHAR(64) NOT NULL COMMENT '对账单号DZ前缀',request_key VARCHAR(64) NOT NULL COMMENT '任务幂等键',request_hash CHAR(64) NOT NULL COMMENT '原请求内容摘要',store_code VARCHAR(64) NOT NULL COMMENT '查询路由虚仓，同实仓全部虚仓聚合比较',owner_code VARCHAR(64) NOT NULL COMMENT '本次货主',real_store VARCHAR(64) NOT NULL COMMENT '本次实仓',method VARCHAR(32) NOT NULL COMMENT 'inventory.query多商品或stock.query分页批次',connection_id BIGINT NOT NULL COMMENT '原仓库连接ID，用于配置引用索引',scope_json MEDIUMTEXT NOT NULL COMMENT 'SKU、批次及全部虚仓范围',scope_hash CHAR(64) NOT NULL COMMENT '规范范围摘要，定位同范围最新成功快照',route_json MEDIUMTEXT NOT NULL COMMENT '原连接映射快照，不含密钥',
 state VARCHAR(24) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING排队、RUNNING查询、COMPLETED有结果、FAILED查询失败',result_json MEDIUMTEXT NULL COMMENT '本次双边原始快照和待入账证据',difference_count INT NOT NULL DEFAULT 0 COMMENT '实物不符行数',attention_count INT NOT NULL DEFAULT 0 COMMENT '冻结不符或字段缺失等待核查行数',oms_snapshot_at DATETIME NULL COMMENT 'OMS快照时间',wms_snapshot_at DATETIME NULL COMMENT 'WMS响应接收时间，非仓库保证一致性时点',
 lease_token VARCHAR(64) NULL COMMENT '执行租约',lease_until DATETIME NULL COMMENT '租约到期',attempts INT NOT NULL DEFAULT 0 COMMENT '执行次数',next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '失败重试时间',last_error VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '查询错误，缺失不能当作零库存',created_by VARCHAR(64) NOT NULL COMMENT '发起人',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '任务创建时间',
 UNIQUE KEY company_sn(company_code,document_sn) COMMENT '对账单号唯一',UNIQUE KEY company_request(company_code,request_key) COMMENT '创建幂等',KEY latest_scope(company_code,scope_hash,state,id) COMMENT '同范围最新成功快照，待办不重复显示过期差异',KEY company_connection(company_code,connection_id,id) COMMENT '配置引用追溯',KEY company_page(company_code,create_time,id) COMMENT '日期分页',KEY due_work(company_code,state,next_attempt_at,id) COMMENT '到期查询任务'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='库存对账快照；查询本身绝不覆盖OMS库存';
CREATE TABLE IF NOT EXISTS warehouse_stock_adjustment (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '差异调整申请ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',document_sn VARCHAR(64) NOT NULL COMMENT '调整单号TZ前缀',reconciliation_id BIGINT NOT NULL COMMENT '本次对账证据ID',request_key VARCHAR(64) NOT NULL COMMENT '创建幂等键',request_hash CHAR(64) NOT NULL COMMENT '不可变申请摘要',state VARCHAR(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT待审核、APPROVED待入账、POSTED已入账、REJECTED驳回',payload_json MEDIUMTEXT NOT NULL COMMENT '具体虚仓批次质量、差量及全范围库存版本',reason VARCHAR(1000) NOT NULL COMMENT '真实盘盈盘亏原因',evidence VARCHAR(1000) NOT NULL COMMENT '仓库盘点和待入账核查凭证',control_version BIGINT NOT NULL DEFAULT 1 COMMENT '审核版本',created_by VARCHAR(64) NOT NULL COMMENT '申请人',reviewed_by VARCHAR(64) NOT NULL DEFAULT '' COMMENT '审核人',attempts INT NOT NULL DEFAULT 0 COMMENT '入账尝试次数',next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '失败入账退避时间',lease_token VARCHAR(64) NULL COMMENT '调整入账租约',lease_until DATETIME NULL COMMENT '调整租约到期',last_error VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '未完成入账错误',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
 UNIQUE KEY company_request(company_code,request_key) COMMENT '重复申请幂等',UNIQUE KEY reconciliation_once(company_code,reconciliation_id) COMMENT '同一快照仅可有一张调整单',KEY company_state(company_code,state,id) COMMENT '审核及补偿扫描'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='独立盘盈盘亏审核单；同快照只能调整一次且版本变化须重新对账';
CREATE TABLE IF NOT EXISTS warehouse_inventory_report (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '仓库盘点通知证据ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',connection_id BIGINT NOT NULL COMMENT '验签连接ID',message_id VARCHAR(128) NOT NULL COMMENT '仓库outBizCode及分页身份',payload_hash CHAR(64) NOT NULL COMMENT '消息内容摘要',owner_code VARCHAR(64) NOT NULL COMMENT '仓库货主',warehouse_code VARCHAR(64) NOT NULL COMMENT '仓库编码',check_order VARCHAR(64) NOT NULL COMMENT '仓库盘点单',payload_json MEDIUMTEXT NOT NULL COMMENT '有符号变化量和盘点总量，通知仅留证不自动改账',source_log_id BIGINT NOT NULL COMMENT '原报文日志',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收到时间',
 UNIQUE KEY original_message(company_code,connection_id,message_id) COMMENT '原通知分页幂等',KEY company_page(company_code,create_time,id) COMMENT '最近盘点证据查询'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='奇门inventory.report盘点通知，变化量与库存查询绝对值严格区分';
CREATE TABLE IF NOT EXISTS warehouse_control_audit (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '人工业务操作记录ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',kind VARCHAR(16) NOT NULL COMMENT 'TRANSFER调拨、RECONCILIATION库存对账',document_id BIGINT NOT NULL COMMENT '原调拨或对账业务ID',action VARCHAR(32) NOT NULL COMMENT '创建审核停止重试收回及差异调整动作',actor VARCHAR(64) NOT NULL COMMENT '实际登录操作人',reason VARCHAR(1500) NOT NULL COMMENT '操作原因、关联单及凭证摘要',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交操作时间',
 KEY document_history(company_code,kind,document_id,id) COMMENT '按原业务读取最近操作，记录仅追加'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='库存对账及调拨人工决策审计，仓库事实另查签名回传和库存流水';
